package org.broadinstitute.hellbender.engine;

import htsjdk.samtools.util.Locatable;
import org.broadinstitute.barclay.argparser.Argument;
import org.broadinstitute.hellbender.engine.filters.ReadFilter;
import org.broadinstitute.hellbender.utils.SimpleInterval;
import org.broadinstitute.hellbender.utils.IntervalUtils;

import java.util.*;

/**
 * Base class for walkers that process assembly regions.
 * Subclasses must implement apply(AssemblyRegion) and assemblyRegionEvaluator().
 */
public abstract class AssemblyRegionWalker extends GATKTool {

    @Argument(fullName = "assembly-region-padding", doc = "Padding around assembly regions")
    protected int assemblyRegionPadding = 100;

    @Argument(fullName = "min-assembly-region-size", doc = "Minimum assembly region size")
    protected int minAssemblyRegionSize = 50;

    @Argument(fullName = "max-assembly-region-size", doc = "Maximum assembly region size")
    protected int maxAssemblyRegionSize = 300;

    @Argument(fullName = "activity-profile-out", doc = "Output activity profile", optional = true)
    protected String activityProfileOut = null;

    private List<MultiIntervalLocalReadShard> readShards;

    @Override
    protected final void onStartup() {
        super.onStartup();
        initializeAssemblyRegionOutputStreams();
    }

    protected void initializeAssemblyRegionOutputStreams() {
        // Initialize output streams for activity profiles if requested
    }

    /**
     * Main traversal method. Iterates over read shards and processes each one.
     */
    @Override
    public final void traverse() {
        logger.info("[DEBUG] Entering traverse() method");

        final List<SimpleInterval> intervals = hasIntervals()
            ? intervalArgumentCollection.getIntervals(getHeaderForReads().getSequenceDictionary())
            : IntervalUtils.getAllIntervalsForReference(getHeaderForReads().getSequenceDictionary());

        logger.info("[DEBUG] Before calling makeReadShards()");
        readShards = makeReadShards(intervals);
        logger.info("[DEBUG] makeReadShards() returned " + readShards.size() + " shards");

        for (final MultiIntervalLocalReadShard shard : readShards) {
            logger.info("[DEBUG] Processing shard: " + shard.getIntervals());
            shard.setReadFilter(makeReadFilter());
            shard.setDownsampler(getDownsampler());

            processReadShard(shard, getReferenceDataSource(),
                assemblyRegionEvaluator());
        }
    }

    /**
     * Creates read shards from intervals, grouping by contig.
     */
    private List<MultiIntervalLocalReadShard> makeReadShards(final List<SimpleInterval> intervals) {
        final List<MultiIntervalLocalReadShard> shards = new ArrayList<>();

        // Group intervals by contig
        final List<List<SimpleInterval>> intervalsGroupedByContig =
            IntervalUtils.groupIntervalsByContig(intervals);

        for (int contigIndex = 0; contigIndex < intervalsGroupedByContig.size(); contigIndex++) {
            final List<SimpleInterval> allIntervalsOnContig = intervalsGroupedByContig.get(contigIndex);
            final List<SimpleInterval> paddedIntervals =
                IntervalUtils.getIntervalsWithFlanks(allIntervalsOnContig, assemblyRegionPadding,
                    getHeaderForReads().getSequenceDictionary());

            shards.add(new MultiIntervalLocalReadShard(allIntervalsOnContig,
                assemblyRegionPadding, reads));
        }
        return shards;
    }

    /**
     * Process a single read shard by iterating over assembly regions.
     */
    private void processReadShard(MultiIntervalLocalReadShard shard,
                                   ReferenceDataSource reference,
                                   AssemblyRegionEvaluator evaluator) {
        final Iterator<AssemblyRegion> assemblyRegionIter =
            new AssemblyRegionIterator(shard, getHeaderForReads(), reference, evaluator,
                minAssemblyRegionSize, maxAssemblyRegionSize,
                assemblyRegionPadding, getActiveProbThreshold(),
                getIncludeReadsWithDeletionsInIsActivePileups());

        while (assemblyRegionIter.hasNext()) {
            final AssemblyRegion assemblyRegion = assemblyRegionIter.next();
            logger.debug("[DEBUG] Assembly region: " + assemblyRegion.getSpan() +
                " reads=" + assemblyRegion.getReads().size() +
                " isActive=" + assemblyRegion.isActive());

            apply(assemblyRegion, reference, null);

            progressMeter.update(assemblyRegion.getSpan());
        }
    }

    /**
     * Subclasses must implement this to process each assembly region.
     */
    public abstract void apply(final AssemblyRegion region,
                               final ReferenceDataSource referenceDataSource,
                               final Object featureContext);

    /**
     * Subclasses must provide an evaluator that determines region activity.
     */
    public abstract AssemblyRegionEvaluator assemblyRegionEvaluator();

    protected double getActiveProbThreshold() {
        return 0.002;
    }

    protected boolean getIncludeReadsWithDeletionsInIsActivePileups() {
        return true;
    }
}

package org.broadinstitute.hellbender.engine;

import htsjdk.samtools.SAMFileHeader;
import org.broadinstitute.hellbender.utils.SimpleInterval;
import org.broadinstitute.hellbender.utils.pileup.ReadPileup;
import org.broadinstitute.hellbender.utils.read.GATKRead;

import java.util.*;

/**
 * Iterates over AssemblyRegions within a read shard. Uses a locus iterator to compute
 * pileups at each position, calls isActive() to build an activity profile, then
 * segments the profile into active/inactive assembly regions.
 */
public class AssemblyRegionIterator implements Iterator<AssemblyRegion> {

    private final MultiIntervalLocalReadShard shard;
    private final SAMFileHeader header;
    private final ReferenceDataSource reference;
    private final AssemblyRegionEvaluator evaluator;
    private final int minRegionSize;
    private final int maxRegionSize;
    private final int assemblyRegionPadding;
    private final double activeProbThreshold;
    private final boolean includeReadsWithDeletions;

    private final Iterator<AlignmentContext> locusIterator;
    private final ActivityProfile activityProfile;
    private final Queue<AssemblyRegion> pendingRegions;
    private AssemblyRegion nextRegion;

    // Read cache for filling regions with overlapping reads
    private final List<GATKRead> readCache;
    private int readCacheEndPosition;

    public AssemblyRegionIterator(MultiIntervalLocalReadShard shard,
                                  SAMFileHeader header,
                                  ReferenceDataSource reference,
                                  AssemblyRegionEvaluator evaluator,
                                  int minRegionSize, int maxRegionSize,
                                  int assemblyRegionPadding,
                                  double activeProbThreshold,
                                  boolean includeReadsWithDeletions) {
        this.shard = shard;
        this.header = header;
        this.reference = reference;
        this.evaluator = evaluator;
        this.minRegionSize = minRegionSize;
        this.maxRegionSize = maxRegionSize;
        this.assemblyRegionPadding = assemblyRegionPadding;
        this.activeProbThreshold = activeProbThreshold;
        this.includeReadsWithDeletions = includeReadsWithDeletions;

        this.locusIterator = shard.getLocusIterator(header, includeReadsWithDeletions);
        this.activityProfile = new BandPassActivityProfile(maxRegionSize,
            activeProbThreshold, header);
        this.pendingRegions = new LinkedList<>();
        this.readCache = new ArrayList<>();
        this.readCacheEndPosition = -1;

        this.nextRegion = loadNextAssemblyRegion();
    }

    @Override
    public boolean hasNext() {
        return nextRegion != null;
    }

    @Override
    public AssemblyRegion next() {
        if (!hasNext()) throw new NoSuchElementException();
        final AssemblyRegion toReturn = nextRegion;
        nextRegion = loadNextAssemblyRegion();
        return toReturn;
    }

    /**
     * Core method: loads the next assembly region by consuming locus pileups,
     * computing activity probabilities, and segmenting into regions.
     */
    private AssemblyRegion loadNextAssemblyRegion() {
        // First check if we have pending regions from a previous segmentation
        if (!pendingRegions.isEmpty()) {
            AssemblyRegion region = pendingRegions.poll();
            fillNextAssemblyRegionWithReads(region);
            return region;
        }

        // Consume locus pileups and build activity profile
        while (locusIterator.hasNext()) {
            final AlignmentContext pileup = locusIterator.next();

            logger.debug("[DEBUG] New Pileup position = " + pileup.getContig() + ":" +
                pileup.getStart() + "-" + pileup.getEnd() +
                " depth=" + pileup.getBasePileup().size());

            // Call isActive to get activity probability for this position
            final ActivityProfileState state = evaluator.isActive(pileup, reference, null);

            // Add to the activity profile
            activityProfile.add(state);

            // Check if the profile can be segmented into regions
            final List<AssemblyRegion> newRegions = activityProfile.popReadyAssemblyRegions(
                assemblyRegionPadding, minRegionSize, maxRegionSize,
                shard.getIntervals(), header);

            if (!newRegions.isEmpty()) {
                for (AssemblyRegion r : newRegions) {
                    pendingRegions.add(r);
                }
                AssemblyRegion region = pendingRegions.poll();
                fillNextAssemblyRegionWithReads(region);
                return region;
            }
        }

        // Flush remaining activity profile
        final List<AssemblyRegion> finalRegions = activityProfile.popReadyAssemblyRegions(
            assemblyRegionPadding, minRegionSize, maxRegionSize,
            shard.getIntervals(), header);
        for (AssemblyRegion r : finalRegions) {
            pendingRegions.add(r);
        }

        if (!pendingRegions.isEmpty()) {
            AssemblyRegion region = pendingRegions.poll();
            fillNextAssemblyRegionWithReads(region);
            return region;
        }

        return null;  // No more regions
    }

    /**
     * Fills an assembly region with reads that overlap the region's padded span.
     * Uses a read cache to avoid re-reading from the shard.
     *
     * IMPORTANT: Downsampling occurs here - reads are filtered through the shard's
     * downsampler before being added to the region.
     */
    private void fillNextAssemblyRegionWithReads(final AssemblyRegion region) {
        final SimpleInterval paddedSpan = region.getPaddedSpan();

        // Extend read cache if needed
        while (readCacheEndPosition < paddedSpan.getEnd() && shard.hasNext()) {
            final GATKRead read = shard.next();
            readCache.add(read);
            readCacheEndPosition = Math.max(readCacheEndPosition, read.getEnd());
        }

        // Add overlapping reads to the region
        for (final GATKRead read : readCache) {
            if (read.overlaps(paddedSpan)) {
                int lowBQ = 0, lowMQ = 0;
                for (var pe : read.getBaseQualities()) {
                    if (pe < 10) lowBQ++;
                }
                if (read.getMappingQuality() == 0) lowMQ++;
                region.add(read);
            }
        }

        // Trim cache: remove reads that end before the region start
        readCache.removeIf(r -> r.getEnd() < region.getSpan().getStart());
    }
}

package org.broadinstitute.hellbender.engine;

import htsjdk.samtools.SAMFileHeader;
import org.broadinstitute.hellbender.engine.filters.ReadFilter;
import org.broadinstitute.hellbender.utils.SimpleInterval;
import org.broadinstitute.hellbender.utils.read.GATKRead;

import java.util.*;

/**
 * A shard of reads covering multiple intervals on a single contig.
 * Provides an iterator over reads and a locus iterator for pileups.
 */
public final class MultiIntervalLocalReadShard implements MultiIntervalShard<GATKRead> {

    private final List<SimpleInterval> intervals;
    private final int padding;
    private final ReadsDataSource readsSource;
    private ReadFilter readFilter;
    private Object downsampler;

    public MultiIntervalLocalReadShard(List<SimpleInterval> intervals, int padding,
                                        ReadsDataSource readsSource) {
        this.intervals = intervals;
        this.padding = padding;
        this.readsSource = readsSource;
    }

    public List<SimpleInterval> getIntervals() {
        return Collections.unmodifiableList(intervals);
    }

    public List<SimpleInterval> getPaddedIntervals() {
        List<SimpleInterval> padded = new ArrayList<>();
        for (SimpleInterval interval : intervals) {
            padded.add(interval.expandWithinContig(padding,
                readsSource.getSequenceDictionary()));
        }
        return padded;
    }

    public void setReadFilter(ReadFilter filter) {
        this.readFilter = filter;
    }

    public void setDownsampler(Object downsampler) {
        this.downsampler = downsampler;
    }

    /**
     * Returns a locus iterator that produces AlignmentContext (pileup) objects
     * at each genome position covered by the intervals.
     * The downsampler is applied during iteration.
     */
    public Iterator<AlignmentContext> getLocusIterator(SAMFileHeader header,
                                                        boolean includeReadsWithDeletions) {
        return new LocusIteratorByState(
            readsSource.query(getPaddedIntervals()),
            downsampler,
            includeReadsWithDeletions,
            header);
    }

    // Iterator<GATKRead> interface for raw read access
    private Iterator<GATKRead> readIterator;

    public boolean hasNext() {
        if (readIterator == null) {
            readIterator = readsSource.query(getPaddedIntervals()).iterator();
        }
        return readIterator.hasNext();
    }

    public GATKRead next() {
        return readIterator.next();
    }
}

package org.broadinstitute.hellbender.engine;

/**
 * Base class for all GATK tools. Manages lifecycle: onStartup -> doWork -> onShutdown.
 * doWork() calls traverse() which subclasses implement.
 */
public abstract class GATKTool {
    protected final org.apache.logging.log4j.Logger logger =
        org.apache.logging.log4j.LogManager.getLogger(this.getClass());

    protected ProgressMeter progressMeter;
    protected IntervalArgumentCollection intervalArgumentCollection;
    protected ReadsDataSource reads;

    /**
     * Template method called by the GATK framework.
     */
    public final Object doWork() {
        progressMeter = new ProgressMeter(1.0);
        onStartup();
        progressMeter.start();
        traverse();
        onShutdown();
        return null;
    }

    protected void onStartup() {
        // Subclasses can override for initialization
    }

    protected void onShutdown() {
        // Subclasses can override for cleanup
    }

    public abstract void traverse();

    protected boolean hasIntervals() {
        return intervalArgumentCollection != null &&
            intervalArgumentCollection.intervalsSpecified();
    }

    protected SAMFileHeader getHeaderForReads() {
        return reads.getHeader();
    }

    protected ReferenceDataSource getReferenceDataSource() {
        return null; // Overridden by subclasses that need reference
    }

    protected ReadFilter makeReadFilter() {
        return ReadFilter.ALLOW_ALL;
    }

    protected Object getDownsampler() {
        return null; // Overridden by subclasses that need downsampling
    }
}

package org.broadinstitute.hellbender.tools.walkers.haplotypecaller;

import org.broadinstitute.hellbender.engine.*;
import org.broadinstitute.hellbender.utils.pileup.ReadPileup;
import org.broadinstitute.hellbender.utils.pileup.PileupElement;

/**
 * Core engine for the HaplotypeCaller. Implements AssemblyRegionEvaluator to
 * determine active regions and performs local assembly + variant calling.
 */
public final class HaplotypeCallerEngine implements AssemblyRegionEvaluator {

    private final MinimalGenotypingEngine genotypingEngine;
    private final HaplotypeCallerArgumentCollection hcArgs;

    public HaplotypeCallerEngine(HaplotypeCallerArgumentCollection hcArgs,
                                  Object header, Object reference) {
        this.hcArgs = hcArgs;
        this.genotypingEngine = new MinimalGenotypingEngine(hcArgs.standardArgs);
    }

    /**
     * Determines whether a given pileup position represents an "active" region
     * that needs local assembly. Uses a simplified genotyping approach.
     *
     * @param context The pileup at this position
     * @param ref Reference data source
     * @param features Feature context (unused in basic mode)
     * @return ActivityProfileState with probability of activity [0.0, 1.0]
     */
    @Override
    public ActivityProfileState isActive(final AlignmentContext context,
                                          final ReferenceDataSource ref,
                                          final Object features) {
        if (context == null || context.getBasePileup().size() == 0) {
            return new ActivityProfileState(context.getLocation(), 0.0);
        }

        final ReadPileup pileup = context.getBasePileup();

        // Use genotyping engine to compute activity probability
        // based on read evidence at this position
        final double activityProb = genotypingEngine.calculateActivityProbability(pileup);

        return new ActivityProfileState(
            context.getLocation(),
            activityProb,
            pileup.size()
        );
    }
}
